	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != HPBAR_HUD)
		{
			return;
		}
		if (client.getVarbitValue(VarbitID.PLAYER_IS_IN_NIGHTMARE_CHALLENGE) == 1 && phosaniBoss != null)
		{
			int shield = client.getVarbitValue(HPBAR_HUD);
			phosaniBoss.setCurrentHealth(shield);
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPCComposition oldNpc = event.getOld();
		NPC newNpc = event.getNpc();
		int oldNpcId = oldNpc.getId();
		int newNpcId = newNpc.getId();

		if (TOTEMS_READY.containsKey(newNpcId))
		{
			totems.put(newNpcId, new PhosaniTotem(newNpc, 0, 200, config));
		}
		else if (TOTEMS_CHARGED.contains(newNpcId))
		{
			totems.remove(oldNpcId);
		}
		else if (PHOSANI_ACTIVE.contains(newNpcId))
		{
			if (newNpcId == NpcID.NIGHTMARE_CHALLENGE_PHASE_05)
			{
				phosaniBoss = new PhosaniBoss(newNpc, 150, 150, config);
			}
			else
			{
				phosaniBoss = new PhosaniBoss(newNpc, 400, 400, config);
			}
		}
		else if (PHOSANI_INACTIVE.contains(newNpcId) || PHOSANI_ACTIVE.contains(oldNpcId))
		{
			phosaniBoss = null;
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		int npcId = npc.getId();
		int index = npc.getIndex();
		int key = -(npcId + index);

		if (npcId == NpcID.NIGHTMARE_CHALLENGE_PARASITE || npcId == NpcID.NIGHTMARE_CHALLENGE_PARASITE_WEAK)
		{
			adds.put(key, new Parasite(npc, config));
		}
		else if (npcId == NpcID.NIGHTMARE_CHALLENGE_HUSK_RANGED)
		{
			adds.put(key, new RangedHusk(npc, config));
		}
		else if (npcId == NpcID.NIGHTMARE_CHALLENGE_HUSK_MAGIC)
		{
			adds.put(key, new MagicHusk(npc, config));
		}
		else if (npcId == NpcID.NIGHTMARE_CHALLENGE_SLEEPWALKER)
		{
			adds.put(key, new Sleepwalker(npc, config));
		}
		else if (PHOSANI_INACTIVE.contains(npcId))
		{
			phosaniBoss = null;
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (client.getVarbitValue(VarbitID.PLAYER_IS_IN_NIGHTMARE_CHALLENGE) == 1)
		{
			NPC npc = event.getNpc();
			int npcId = npc.getId();
			int index = npc.getIndex();
			int key = -(npcId + index);
			adds.remove(key);
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender beforeRender)
	{
		if (client.getVarbitValue(VarbitID.PLAYER_IS_IN_NIGHTMARE_CHALLENGE) == 1)
		{
			Widget healthBarWidget = client.getWidget(InterfaceID.HpbarHud.HP);
			if (healthBarWidget != null)
			{
				healthBarWidget.setHidden(config.hideHealthOverlay());
			}

			Widget totemHudWidget = client.getWidget(InterfaceID.NightmareTotems.TOTEMS);
			if (totemHudWidget != null && config.totemHud() != TotemHudStyle.DEFAULT)
			{
				totemHudWidget.setHidden(true);
			}
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (client.getVarbitValue(VarbitID.PLAYER_IS_IN_NIGHTMARE_CHALLENGE) == 1)
		{
			GameObject object = event.getGameObject();

			if (object.getId() == SPORE_GROWING_ID || object.getId() == SPORE_OBJECT_ID)
			{
				spores.add(new Spore(object, config));
			}
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{

		if (client.getVarbitValue(VarbitID.PLAYER_IS_IN_NIGHTMARE_CHALLENGE) == 1)
		{
			GameObject object = event.getGameObject();
			spores.removeIf(spore -> spore.getGameObject() == object);
		}
	}

	private void clearAll()
	{
		totems.clear();
		phosaniBoss = null;
		adds.clear();
		spores.clear();
		xpDrops.clear();
	}

	@Provides
	PhosaniQolConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PhosaniQolConfig.class);
	}
}

package com.phosaniqol;

import com.phosaniqol.npcs.PhosaniTotem;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Slf4j
public class PhosaniQolTotemHud extends Overlay
{
	private final int PADDING = 6;
	private final int TEXT_BAR_GAP = 2;

	private final PhosaniQolPlugin plugin;
	private final PhosaniQolConfig config;

	@Inject
	public PhosaniQolTotemHud(PhosaniQolPlugin plugin, PhosaniQolConfig config)
	{
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics2D)
	{
		if (config.totemHud() != TotemHudStyle.CUSTOM) return null;
		if (plugin.getTotems().isEmpty()) return null;

		Color textColor = config.totemHudTextColor();
		Color barBackground = config.totemHudBarBackground();
		Color barForeground = config.totemHudBarForeground();
		Color barFull = config.totemHudBarFull();
		Color outlineColor = config.totemHudOutlineColor();
		Font font = config.totemHudFont().getFont();
		int barWidth = config.totemHudBarWidth();
		int barHeight = config.totemHudBarHeight();
		int outlineWidth = config.totemHudOutline();

		FontMetrics fontMetrics = graphics2D.getFontMetrics(font);
		int cellWidth = Math.max(fontMetrics.stringWidth("North West"), barWidth) + PADDING;
		int cellHeight = fontMetrics.getAscent() + TEXT_BAR_GAP + barHeight + PADDING;

		Map<Integer, PhosaniTotem> totems = plugin.getTotems();

		int corner = 0;
		for (var entry: PhosaniQolPlugin.TOTEMS_READY.entrySet())
		{
			int npcId = entry.getKey();
			String name = entry.getValue();
			int column = corner % 2;
			int row = corner / 2;
			int x = (column * cellWidth);
			int y = (row * cellHeight) + fontMetrics.getAscent() + (PADDING / 2);
			int textPadding = ((cellWidth - fontMetrics.stringWidth(name)) / 2);
			int barPadding = ((cellWidth - barWidth) / 2);

			drawText(graphics2D, font, textColor, outlineWidth, outlineColor, x + textPadding, y, name);

			graphics2D.setColor(outlineColor);
			graphics2D.fillRect(x + barPadding - outlineWidth, y + TEXT_BAR_GAP - outlineWidth, barWidth + (outlineWidth * 2), barHeight + (outlineWidth * 2));

			graphics2D.setColor(barBackground);
			graphics2D.fillRect(x + barPadding, y + TEXT_BAR_GAP, barWidth, barHeight);

			if (totems.containsKey(npcId) && totems.get(npcId).getHealthPercent() < 1.0)
			{
				graphics2D.setColor(barForeground);
				graphics2D.fillRect(x + barPadding, y + TEXT_BAR_GAP, (int) (barWidth * totems.get(npcId).getHealthPercent()), barHeight);
			}
			else
			{
				graphics2D.setColor(barFull);
				graphics2D.fillRect(x + barPadding, y + TEXT_BAR_GAP, barWidth, barHeight);
			}

			corner += 1;
		}

		return new Dimension(cellWidth * 2, cellHeight * 2);
	}

	private void drawText(Graphics2D graphics2D, Font font, Color color, int outlineWidth, Color outlineColor, int x, int y, String text)
	{
		graphics2D.setFont(font);
		if (outlineWidth > 0)
		{
			graphics2D.setColor(outlineColor);
			for (int dx = -outlineWidth; dx <= outlineWidth; dx++)
			{
				for (int dy = -outlineWidth; dy <= outlineWidth; dy++)
				{
					if ((dx != 0 || dy != 0) && dx * dx + dy * dy <= outlineWidth * outlineWidth + 1)
					{
						graphics2D.drawString(text, x + dx, y + dy);
					}
				}
			}
		}
		graphics2D.setColor(color);
		graphics2D.drawString(text, x, y);
	}
}

